// Services/DroneIcon.cs
//
// Top-down VTOL QuadPlane icon (wing, 4 lift rotors, V-tail, pusher prop,
// red/green nav lights) used for the live vehicle marker on Flight View's map.
// Nose points UP (north) so SymbolRotation = heading turns it correctly.
//
// Embedded as a 256x256 PNG (base64) so no csproj or file-copy changes are
// needed. Source SVG: tools/drone_icon.svg - re-render with cairosvg if edited.

using System;
using Mapsui.Styles;

namespace InfraDroneDesktop.Services
{
    public static class DroneIcon
    {
        private static int? _bitmapId;

        /// <summary>Mapsui bitmap id, registered once on first use. -1 if registration failed.</summary>
        public static int BitmapId
        {
            get
            {
                if (_bitmapId == null)
                {
                    try
                    {
                        var bytes = Convert.FromBase64String(PngBase64);
                        // byte[] is decoded directly by Mapsui's BitmapHelper (PNG via SKImage).
                        _bitmapId = BitmapRegistry.Instance.Register(bytes);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine("[DroneIcon] Could not register icon: " + ex.Message);
                        _bitmapId = -1;
                    }
                }
                return _bitmapId.Value;
            }
        }

        // 256 px source; 0.25 scale = 64 px on screen.
        public const double DefaultScale = 0.25;

        private const string PngBase64 = "";
    }
}
